syntax:
int num = 50;
int *ptr;          // ptr can hold the address of an int
ptr = &num;        // ptr points to num

cout << num;       // 50, the value
cout << *ptr;      // 50, the value ptr points to (dereference)
*ptr = 75;         // changes num to 75 through the pointer

int *safe = nullptr;      // points to nothing
if (safe != nullptr) {    // always check before using
    cout << *safe;
}

double d = 2.5;
double *pd = &d;   // the pointer type matches the variable type

sample.code:
#include <iostream>
using namespace std;

int main() {
    int num = 50;
    int *ptr;
    ptr = &num;
    cout << "num  = " << num << endl;
    cout << "*ptr = " << *ptr << endl;
    cout << "ptr holds the address of num? " << (ptr == &num) << endl;
    *ptr = 75;
    cout << "num after *ptr = 75: " << num << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    double price = 99.5;
    char grade = 'B';
    double *pp = &price;
    char *pg = &grade;
    *pp = *pp + 0.5;
    *pg = 'A';
    cout << "price = " << price << endl;
    cout << "grade = " << grade << endl;
    int *q = nullptr;
    if (q == nullptr) {
        cout << "q points to nothing" << endl;
    } else {
        cout << "q points to " << *q << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int a = 10, b = 20;
    int *p = &a;
    int *q = p;
    *q = *q + 5;
    p = &b;
    *p = *p * 2;
    cout << a << " " << b << " " << *p << " " << *q << endl;
    return 0;
}

